-- PaceMate 1-D-5D law curriculum reference draft seed (REVIEW ONLY)
-- DO NOT EXECUTE in this drafting step.
-- Scope: 계명대학교 / 법학과 only.
-- No school/department creation, active version, student assignment, course catalog,
-- professor, offering, report, demo data, or graduation calculation is included.
-- The five career links whose source name is 형사소송법 have no exact curriculum
-- local key; they are preserved as held source links and are not inserted.

begin;

do $preflight$
declare
  v_school_id uuid;
  v_department_id uuid;
  v_school_count integer;
  v_department_count integer;
  v_version_count integer;
  v_course_count integer;
  v_requirement_count integer;
  v_exception_count integer;
begin
  select count(*) into v_school_count
  from public.schools where name = '계명대학교';
  if v_school_count <> 1 then
    raise exception 'Expected exactly one 계명대학교 school row, found %', v_school_count;
  end if;

  select id into v_school_id
  from public.schools where name = '계명대학교';

  select count(*) into v_department_count
  from public.departments
  where school_id = v_school_id and name = '법학과';
  if v_department_count <> 1 then
    raise exception 'Expected exactly one 법학과 department row, found %', v_department_count;
  end if;

  select id into v_department_id
  from public.departments
  where school_id = v_school_id and name = '법학과';

  select count(*) into v_version_count
  from public.curriculum_versions
  where school_id = v_school_id
    and department_id = v_department_id
    and version_key = 'law-bluebook-reference-unknown';

  if v_version_count <> 0 then
    raise exception 'Law draft version already exists; refusing duplicate or rerun: %', v_version_count;
  end if;

  select count(*) into v_course_count
  from public.curriculum_courses c
  join public.curriculum_versions v on v.id = c.curriculum_version_id
  where v.school_id = v_school_id and v.department_id = v_department_id
    and v.version_key = 'law-bluebook-reference-unknown';
  select count(*) into v_requirement_count
  from public.curriculum_requirements r
  join public.curriculum_versions v on v.id = r.curriculum_version_id
  where v.school_id = v_school_id and v.department_id = v_department_id
    and v.version_key = 'law-bluebook-reference-unknown';
  select count(*) into v_exception_count
  from public.curriculum_requirement_exceptions e
  join public.curriculum_versions v on v.id = e.curriculum_version_id
  where v.school_id = v_school_id and v.department_id = v_department_id
    and v.version_key = 'law-bluebook-reference-unknown';

  if v_course_count <> 0 or v_requirement_count <> 0 or v_exception_count <> 0 then
    raise exception 'Partial law draft data exists: courses %, requirements %, exceptions %',
      v_course_count, v_requirement_count, v_exception_count;
  end if;
end
$preflight$;

insert into public.curriculum_versions (
  school_id, department_id, version_key, academic_year, version_label,
  admission_year_from, admission_year_to, status, source_title, source_file,
  source_academic_year, source_edition, publication_date, source_verified, notes
)
select s.id, d.id, 'law-bluebook-reference-unknown', null,
  'Law curriculum bluebook (publication year unknown)',
  null, null, 'draft',
  '계명대학교 법학과 Bluebook',
  'docs/reference/bluebooks/law/source.pdf',
  null, null, null, false,
  '참고용 draft. 과목 46개(exact 6, unresolved 40), source career links 123개 중 seeded 118개, 형사소송법 보류 5개. 보류 track: law-school-bar-exam, judicial-scrivener, prosecution-drug-investigation-9th-grade, court-clerical-9th-grade, police-officer-track. exact localKey가 없어 추정 매핑하지 않았으며 공식 졸업 계산에 사용하지 않음.'
from public.schools s
join public.departments d on d.school_id = s.id and d.name = '법학과'
where s.name = '계명대학교';

do $version_check$
declare
  v_school_id uuid;
  v_department_id uuid;
  v_version_id uuid;
  v_version_count integer;
begin
  select id into v_school_id from public.schools where name = '계명대학교';
  select id into v_department_id from public.departments
  where school_id = v_school_id and name = '법학과';

  select count(*) into v_version_count
  from public.curriculum_versions
  where school_id = v_school_id and department_id = v_department_id
    and version_key = 'law-bluebook-reference-unknown' and status = 'draft';
  if v_version_count <> 1 then
    raise exception 'Expected exactly one law draft version, found %', v_version_count;
  end if;

  select id into v_version_id
  from public.curriculum_versions
  where school_id = v_school_id and department_id = v_department_id
    and version_key = 'law-bluebook-reference-unknown' and status = 'draft';

  if exists (
    select 1 from public.curriculum_versions
    where id = v_version_id
      and (admission_year_from is not null or admission_year_to is not null
        or source_verified is not false)
  ) then
    raise exception 'Law draft version safety invariant violated';
  end if;
end
$version_check$;

insert into public.curriculum_courses (
