  "trackCode" text,
  "curriculumCourseLocalKey" text,
  "sourceCourseName" text,
  "recommendedStage" text,
  priority integer,
  "isRequired" boolean,
  "sourcePage" integer
  )
  where e."curriculumCourseLocalKey" is not null
    and not exists (
    select 1 from public.curriculum_courses c
    join public.curriculum_versions v on v.id = c.curriculum_version_id
    where v.version_key = 'law-bluebook-reference-unknown'
      and c.metadata->>'localKey' = e."curriculumCourseLocalKey"
  );
  if v_unresolved_local_key_count <> 0 then
    raise exception 'Career links contain % unknown curriculum local keys', v_unresolved_local_key_count;
  end if;
end
