CourseName":"채권법각론","recommendedStage":"grade-3","priority":11,"isRequired":false,"sourcePage":14},{"trackCode":"court-registration-clerical-9th-grade","curriculumCourseLocalKey":"law-3-1-02","sourceCourseName":"회사법","recommendedStage":"grade-3","priority":12,"isRequired":false,"sourcePage":14},{"trackCode":"court-registration-clerical-9th-grade","curriculumCourseLocalKey":"law-4-2-03","sourceCourseName":"헌법소송법","recommendedStage":"grade-4","priority":13,"isRequired":false,"sourcePage":14},{"trackCode":"court-registration-clerical-9th-grade","curriculumCourseLocalKey":"law-4-1-03","sourceCourseName":"가족법","recommendedStage":"grade-4","priority":14,"isRequired":false,"sourcePage":14},{"trackCode":"court-registration-clerical-9th-grade","curriculumCourseLocalKey":"law-4-2-05","sourceCourseName":"민사법세미나","recommendedStage":"grade-4","priority":15,"isRequired":false,"sourcePage":14},{"trackCode":"court-registration-clerical-9th-grade","curriculumCourseLocalKey":"law-4-2-02","sourceCourseName":"민사집행법","recommendedStage":"grade-4","priority":16,"isRequired":false,"sourcePage":14},{"trackCode":"police-officer-track","curriculumCourseLocalKey":"law-1-1-01","sourceCourseName":"법학개론","recommendedStage":"grade-1","priority":1,"isRequired":false,"sourcePage":15},{"trackCode":"police-officer-track","curriculumCourseLocalKey":"law-1-2-02","sourceCourseName":"형법총론(1)","recommendedStage":"grade-1","priority":2,"isRequired":false,"sourcePage":15},{"trackCode":"police-officer-track","curriculumCourseLocalKey":"law-2-1-03","sourceCourseName":"형법총론(2)","recommendedStage":"grade-2","priority":3,"isRequired":false,"sourcePage":15},{"trackCode":"police-officer-track","curriculumCourseLocalKey":"law-2-2-04","sourceCourseName":"형법각론(1)","recommendedStage":"grade-2","priority":4,"isRequired":false,"sourcePage":15},{"trackCode":"police-officer-track","curriculumCourseLocalKey":"law-2-1-02","sourceCourseName":"헌법(1)","recommendedStage":"grade-2","priority":5,"isRequired":false,"sourcePage":15},{"trackCode":"police-officer-track","curriculumCourseLocalKey":"law-2-2-03","sourceCourseName":"헌법(2)","recommendedStage":"grade-2","priority":6,"isRequired":false,"sourcePage":15},{"trackCode":"police-officer-track","curriculumCourseLocalKey":"law-3-1-06","sourceCourseName":"형사절차와인권","recommendedStage":"grade-2","priority":7,"isRequired":false,"sourcePage":15},{"trackCode":"police-officer-track","curriculumCourseLocalKey":null,"sourceCourseName":"형사소송법","recommendedStage":"grade-3","priority":8,"isRequired":false,"sourcePage":15},{"trackCode":"police-officer-track","curriculumCourseLocalKey":"law-3-1-05","sourceCourseName":"형법각론(2)","recommendedStage":"grade-3","priority":9,"isRequired":false,"sourcePage":15},{"trackCode":"police-officer-track","curriculumCourseLocalKey":"law-3-1-08","sourceCourseName":"경찰헌법","recommendedStage":"grade-3","priority":10,"isRequired":false,"sourcePage":15}]$links$::jsonb) as e(
  "trackCode" text,
  "curriculumCourseLocalKey" text,
  "sourceCourseName" text,
  "recommendedStage" text,
  priority integer,
  "isRequired" boolean,
  "sourcePage" integer
)
join public.curriculum_courses c
  on c.curriculum_version_id = v.id
 and c.metadata->>'localKey' = e."curriculumCourseLocalKey"
where v.version_key = 'law-bluebook-reference-unknown'
  and t.track_code = e."trackCode"
  and e."curriculumCourseLocalKey" is not null;

do $verify$
declare
  v_id uuid;
  v_course_count integer;
  v_exact_count integer;
  v_unresolved_count integer;
  v_requirement_count integer;
  v_exception_count integer;
  v_track_count integer;
  v_link_count integer;
  v_source_link_count integer;
  v_held_link_count integer;
begin
  select id into v_id from public.curriculum_versions
  where version_key = 'law-bluebook-reference-unknown' and status = 'draft';

  select count(*), count(*) filter (where course_id is not null),
    count(*) filter (where course_id is null)
    into v_course_count, v_exact_count, v_unresolved_count
  from public.curriculum_courses where curriculum_version_id = v_id;
  select count(*) into v_requirement_count from public.curriculum_requirements where curriculum_version_id = v_id;
  select count(*) into v_exception_count from public.curriculum_requirement_exceptions where curriculum_version_id = v_id;
  select count(*) into v_track_count from public.career_tracks where curriculum_version_id = v_id;
  select count(*) into v_link_count
  from public.career_track_courses c
  join public.career_tracks t on t.id = c.career_track_id
  where t.curriculum_version_id = v_id;

  select 123, 5 into v_source_link_count, v_held_link_count;

  if v_course_count <> 46 or v_exact_count <> 6 or v_unresolved_count <> 40
     or v_requirement_count <> 3 or v_exception_count <> 5
     or v_track_count <> 11 or v_link_count <> (v_source_link_count - v_held_link_count) then
    raise exception 'Law draft counts mismatch: courses %, exact %, unresolved %, requirements %, exceptions %, tracks %, seeded links %, source links %, held links %',
      v_course_count, v_exact_count, v_unresolved_count, v_requirement_count,
      v_exception_count, v_track_count, v_link_count, v_source_link_count, v_held_link_count;
  end if;

  if exists (
    select 1 from public.curriculum_courses
    where curriculum_version_id = v_id
      and (credits is not null or source_course_code is not null)
  ) then
    raise exception 'Law draft inferred credits or course codes detected';
  end if;
end
$verify$;

commit;
